insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('a2final-diagnosis','W sobotę Marta ___ do Krakowa i zwiedziła muzeum.','["pojechała","pojedzie","jechać"]',0,'Завершённое событие в прошлом требует формы pojechała.',0),
('a2final-diagnosis','Jutro rano ___ bilety na pociąg.','["kupimy","kupiliśmy","kupować"]',0,'Jutro указывает на будущее: kupimy.',1),
('a2final-diagnosis','W mieszkaniu nie ma ___.','["ciepłej wody","ciepła woda","ciepłą wodą"]',0,'После nie ma используется родительный падеж: ciepłej wody.',2),
('a2final-diagnosis','Ten plecak jest ___ niż tamten.','["lżejszy","najlżejszy","lekki od"]',0,'При сравнении двух предметов используется сравнительная степень + niż.',3),
('a2final-diagnosis','Составьте: Перед поездкой стоит проверить прогноз.','["Przed podróżą warto sprawdzić prognozę.","Przed podróż warto sprawdza prognoza.","Podróżą warto prognozę sprawdził."]',0,'После przed нужен творительный, после warto — инфинитив.',4),
('a2final-diagnosis','Ania powiedziała, ___ nie może przyjść, ___ jest chora.','["że; bo","bo; że","dlatego; czy"]',0,'Że вводит содержание сообщения, а bo — его причину.',5),
('a2final-diagnosis','Czytałem tę książkę. Polecam ___.','["ją","go","ich"]',0,'Książka — существительное женского рода, поэтому объект заменяется местоимением ją.',6),
('a2final-diagnosis','Составьте: Я хотел бы подать заявление завтра.','["Chciałbym złożyć wniosek jutro.","Chcę jutro wniosek daj.","Chciałbym złożyłem wniosek jutro."]',0,'Вежливая просьба строится как chciałbym + инфинитив złożyć.',7),
('a2final-quiz','Co powiesz o zakończonym weekendzie?','["W sobotę spotkałem się z przyjaciółmi.","W sobotę spotkam się wczoraj.","W sobotę spotykać przyjaciele."]',0,'Для законченного события используем прошедшее время.',0),
('a2final-quiz','Pociąg odjeżdża ___ Warszawy o siódmej.','["do","w","na"]',0,'Направление к городу передаётся конструкцией do + родительный падеж.',1),
('a2final-quiz','Hydraulik zajmuje się ___.','["naprawą kranu","naprawę kranu","naprawa kran"]',0,'Zajmować się требует творительного падежа: naprawą.',2),
('a2final-quiz','Najpierw ___ raport, a potem wysłałem go kierownikowi.','["napisałem","pisałem do końca","będę pisał"]',0,'Napisałem подчёркивает завершённый результат действия.',3),
('a2final-quiz','Który produkt kosztuje najmniej?','["najtańszy","tańszy niż","bardziej drogi"]',0,'Najtańszy — превосходная степень от tani.',4),
('a2final-quiz','Mam gorączkę. Co powinienem zrobić?','["Powinieneś odpocząć i skontaktować się z lekarzem.","Nie wolno zawsze lekarz.","Odpoczywałeś jutro."]',0,'Powinieneś + инфинитив выражает рекомендацию.',5),
('a2final-quiz','Ola była smutna, ___ nie dostała tej pracy.','["bo","że","dlatego"]',0,'Bo вводит причину эмоционального состояния.',6),
('a2final-quiz','Film był ciekawy, więc poleciłem ___ znajomym.','["go","ją","je"]',0,'Film — мужской род, объект заменяется местоимением go.',7),
('a2final-quiz','Jak grzecznie poprosić o informację w urzędzie?','["Czy może mi pani powiedzieć, gdzie mam podpisać?","Powiedz mi teraz, gdzie podpis!","Gdzie ja podpisuje pani?"]',0,'Czy może mi pani powiedzieć…? — нейтральная официальная просьба.',8),
('a2final-quiz','Jeśli jutro będzie burza, ___.','["zostaniemy w domu","zostaliśmy w domu wczoraj","zostać dom"]',0,'Реальное условие относится к будущему: jeśli będzie…, zostaniemy….',9),
('a2final-quiz','Najpierw zwiedziliśmy zamek, ___ poszliśmy na rynek.','["następnie","ponieważ","chociaż że"]',0,'Następnie связывает последовательные события рассказа.',10),
('a2final-quiz','Что лучше всего завершает связный рассказ?','["Na koniec podsumowałem, czego się nauczyłem.","Bo na koniec i dlatego.","Podsumować ja nauczył."]',0,'Финальный маркер na koniec и правильное прошедшее время создают ясное завершение.',11),
('a2final-reading-check','Dlaczego Lena pojechała do Torunia?','["Na weekend i spotkanie z kuzynką","Żeby złożyć reklamację","Na wizytę u lekarza"]',0,'Лена планировала выходные и встречу с двоюродной сестрой.',0),
('a2final-reading-check','Jaki problem pojawił się po przyjeździe?','["W pokoju nie działało ogrzewanie","Lena zgubiła paszport","Muzeum było zamknięte"]',0,'В комнате было холодно, потому что не работало отопление.',1),
('a2final-reading-check','Jak rozwiązano problem w hostelu?','["Recepcjonistka dała Lenie inny pokój","Lena kupiła nowy grzejnik","Kuzynka naprawiła okno"]',0,'После спокойного объяснения Лена получила другую комнату.',2),
('a2final-reading-check','Dlaczego Lena i Zosia zmieniły plan spaceru?','["Zaczął padać deszcz","Nie miały biletów","Pokłóciły się"]',0,'Из-за дождя они выбрали музей вместо долгой прогулки.',3),
('a2final-reading-check','Co Lena zrobiła przed powrotem?','["Kupiła syrop i zachowała paragon","Złożyła wniosek o paszport","Oddała bilet kolejowy"]',0,'В аптеке она купила сироп и сохранила чек.',4),
('a2final-reading-check','Jaki jest główny wniosek Leny?','["Spokój i jasne wyjaśnienie pomagają rozwiązać problem","Każdą podróż trzeba odwołać","W mieście nie warto pytać o pomoc"]',0,'В конце Лена подводит итог: спокойствие и ясная просьба помогают.',5);
